mapper.select:
SELECT * FROM table_info
WHERE datasource_id = #{datasourceId}
ORDER BY table_name ASC, id ASC

mapper.update:
UPDATE table_info
table_name = #{tableName}, table_description = #{tableDescription}, data_granularity = #{dataGranularity}, domain = #{domain}, is_visible = #{isVisible}, update_time = #{updateTime},
WHERE id = #{id}

UPDATE table_info
table_name = #{tableName}, physical_table_description = #{physicalTableDescription}, physical_status = #{physicalStatus}, update_time = #{updateTime},
WHERE id = #{id}

UPDATE table_info
SET table_description = #{description}
WHERE id = #{id}
  AND (table_description IS NULL OR table_description = '')

UPDATE table_info SET table_description = physical_table_description, data_granularity = NULL, domain = 'default', is_visible = 1, update_time = NOW() WHERE datasource_id = #{datasourceId} AND id IN
#{id}
AND (physical_status IS NULL OR physical_status <> 0)

mapper.delete:
DELETE FROM table_info
WHERE datasource_id = #{datasourceId}
  AND id IN

    #{id}

  AND physical_status = 0
